errorSummary: kit.errorSummary(error ? { [fieldName]: error } : undefined, {
      href: () => (found.length > 0 ? `#${fieldName}` : '#q')
    }),

{% macro pickerSelectCell(fieldName, row, pickerCopy) %}
  {% set selectLabel %}<span class="govuk-visually-hidden">{{ pickerCopy.selectRowPrefix }} {{ row.name }}</span>{% endset %}
  {{ govukRadios({
    idPrefix: row.idPrefix,
    name: fieldName,
    classes: "govuk-radios--small",
    items: [{
      value: row.id,
      html: selectLabel,
      checked: row.checked
    }]
  }) }}
{% endmacro %}

{% macro pickerAddressCell(row) %}
  {%- for line in row.addressLines -%}
    {{ line }}{% if not loop.last %}<br>{% endif %}
  {%- endfor -%}
{% endmacro %}

{% if picker.pagination %}
      {{ govukPagination(picker.pagination) }}
    {% endif %}

const numbersToShow = (page, totalPages) => {
  const eitherSideOfCurrent = 1
  const shown = [
    FIRST_PAGE,
    page - eitherSideOfCurrent,
    page,
    page + eitherSideOfCurrent,
    totalPages
  ].filter((number) => number >= FIRST_PAGE && number <= totalPages)
  return [...new Set(shown)].sort((left, right) => left - right)
}

pagination: {
    previous: 'Previous',
    next: 'Next'
  }

for (const link of everyPagingLink(picker)) {
            expect(link.href).toContain('q=record')
            expect(link.href).toContain('selected=record-3')
          }

const params = new URLSearchParams()
  if (query) {
    params.set('q', query)
  }
  if (page > FIRST_PAGE) {
    params.set('page', String(page))
  }
  if (selectedId) {
    params.set('selected', selectedId)
  }

if (servedPage !== resultsPage) {
    request.logger.info(
      {
        journeyId: current.journey.journeyId,
        fieldName,
        requestedPage: resultsPage,
        servedPage
      },
      'Address picker page is past the last page, serving the last page'
    )
  }

export const pickerRoutes = ({ inScope = () => true, ...settings }) => {
  const picker = { ...settings, inScope }
  return kit.pageRoutes(picker.page, {
    get: (request, h) => getPicker(picker, request, h),
    post: (request, h) => postPicker(picker, request, h)
  })
}

return renderPickerPage(picker, request, h, current, {
    query: request.query.q ?? '',
    resultsPage: resultsPageToOpen(
      request,
      picker.fieldName,
      request.query.page
    ),
    selectedId:
      request.query.selected ?? current.answers[picker.fieldName]?.pickedFromId
  })

if (!selectedId) {
    request.logger.info(
      { journeyId, fieldName },
      'Address picker saved with no address chosen, nothing committed'
    )
    return { outcome: SELECTION.nothingChosen }
  }

const record = await chosenFor(organisationIdOf(request), selectedId, role)
  if (!record) {
    kit.logRefusal(request, {
      fieldErrors: { [fieldName]: notInBookMessage },
      reason: 'not-in-address-book',
      addressId: selectedId
    })
    return { outcome: SELECTION.notInBook }
  }

postedPickerState(request, picker.fieldName, payload, {
        selectedId: '',
        error: picker.copy.errors[picker.fieldName]
      })

const record = await addressBook.party(orgId, selectedId)
  return record && !record.deleted && addressBook.offeredForRole(record, role)
    ? record
    : undefined

committed = await state.commit(request, h, {
        [picker.fieldName]: answerForPickedParty(chosen)
      })

postedPickerState(request, picker.fieldName, payload, {
        selectedId: chosen.id,
        recoverableError: true
      })
  ).code(HTTP_STATUS_INTERNAL_SERVER_ERROR)

